import axios from '@/utils/axiosConfig';
import AutoComplete from 'primevue/autocomplete';
import Dropdown from 'primevue/dropdown';
export default {
  name: 'LeaveForm',
  components: {
    AutoComplete,
    Dropdown
  },
  async created() {
    await this.loadWorkHours();
    await this.loadLeaveTypes();
    await this.loadUsers();
    await this.loadQuotaData();
    await this.loadHolidays();
    await this.checkLevel2Approver();
    // Initialize with limited users
    this.filteredUsers = this.users.slice(0, this.maxDisplayUsers);
  },
  data() {
    return {
      isLevel2Approver: false,
      selectedLeaveUser: null,
      allUsersForLeave: [],
      calendarViewDate: new Date(),
      formData: {
        leaveType: '',
        startDate: null,
        startTime: null,
        endDate: null,
        endTime: null,
        startDateTime: null,
        endDateTime: null,
        reason: '',
        delegationOption: 'no',
        delegateName: '',
        delegatePosition: '',
        delegateDepartment: '',
        delegateContact: '',
        workDetails: '',
        attachments: [],
        quickLeave: null
      },
      allowedTimes: [],
      leaveTypes: [],
      delegationOptions: [{
        label: 'ไม่มีการมอบหมายงาน',
        value: 'no'
      }, {
        label: 'มีการมอบหมายงาน',
        value: 'yes'
      }],
      users: [],
      filteredUsers: [],
      selectedDelegate: null,
      maxDisplayUsers: 50,
      quotaData: {},
      selectedQuota: null,
      holidays: [],
      workHours: {
        start_time: '09:00',
        end_time: '18:00',
        lunch_start: '12:00',
        lunch_end: '13:00'
      }
    };
  },
  watch: {
    'formData.startDate'() {
      this.updateStartDateTime();
    },
    'formData.endDate'() {
      this.updateEndDateTime();
    }
  },
  computed: {
    currentUserName() {
      const firstName = localStorage.getItem('soc_firstname') || '';
      const lastName = localStorage.getItem('soc_lastname') || '';
      return `${firstName} ${lastName}`.trim();
    },
    currentUserRole() {
      return localStorage.getItem('soc_role') || '';
    },
    currentUserPosition() {
      return localStorage.getItem('soc_position') || 'ไม่ระบุตำแหน่ง';
    },
    leaveUserPosition() {
      if (this.isLevel2Approver && this.selectedLeaveUser) {
        return this.selectedLeaveUser.position || 'ไม่ระบุตำแหน่ง';
      }
      return this.currentUserPosition;
    },
    selectedLeaveTypeAdvanceDays() {
      if (!this.formData.leaveType || this.formData.leaveType === 'sick' || this.formData.leaveType === 'ลาป่วย') return 0;
      const type = this.leaveTypes.find(t => t.value === this.formData.leaveType);
      return type?.advance_days || 0;
    },
    minStartDate() {
      // ถ้าเป็นผู้อนุมัติขั้นที่ 2 สามารถเลือกวันย้อนหลังได้
      if (this.isLevel2Approver) {
        const pastDate = new Date();
        pastDate.setFullYear(pastDate.getFullYear() - 1); // ย้อนหลังได้ 1 ปี
        pastDate.setHours(0, 0, 0, 0);
        return pastDate;
      }

      // ลาป่วย ย้อนหลังได้ 2 วัน
      if (this.formData.leaveType === 'sick' || this.formData.leaveType === 'ลาป่วย') {
        const now = new Date();
        const pastDate = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 2);
        return pastDate;
      }
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const advanceDays = this.selectedLeaveTypeAdvanceDays;
      if (advanceDays > 0) {
        return this.addWorkingDays(today, advanceDays);
      }
      return today;
    },
    holidayDates() {
      return this.holidays.map(h => {
        const d = new Date(h.holiday_date);
        d.setHours(0, 0, 0, 0);
        return d.getTime();
      });
    },
    disabledDates() {
      if (this.isLevel2Approver) return [];
      return this.holidays.map(h => new Date(h.holiday_date));
    },
    disabledDays() {
      if (this.isLevel2Approver) return [];
      return [0, 6];
    },
    formatMinDate() {
      return this.minStartDate.toLocaleDateString('th-TH', {
        day: 'numeric',
        month: 'short',
        year: 'numeric'
      });
    },
    calculateDays() {
      if (this.formData.startDateTime && this.formData.endDateTime) {
        const start = new Date(this.formData.startDateTime);
        const end = new Date(this.formData.endDateTime);
        const [ws, wsm = 0] = this.workHours.start_time.split(':').map(Number);
        const [we, wem = 0] = this.workHours.end_time.split(':').map(Number);
        const [ls, lsm = 0] = this.workHours.lunch_start.split(':').map(Number);
        const [le, lem = 0] = this.workHours.lunch_end.split(':').map(Number);
        const hoursPerDay = (ls * 60 + lsm - (ws * 60 + wsm) + (we * 60 + wem) - (le * 60 + lem)) / 60;
        let totalHours = 0;
        const startDate = new Date(start);
        startDate.setHours(0, 0, 0, 0);
        const endDate = new Date(end);
        endDate.setHours(0, 0, 0, 0);
        if (startDate.getTime() === endDate.getTime()) {
          // วันเดียวกัน - คำนวณชั่วโมงตรงๆ (ถ้าไม่ใช่วันหยุด)
          const day = startDate.getDay();
          if (day !== 0 && day !== 6 && !this.holidayDates.includes(startDate.getTime())) {
            totalHours = this.calculateWorkHours(start, end);
          }
        } else {
          // หลายวัน
          const current = new Date(startDate);
          while (current <= endDate) {
            const day = current.getDay();
            const isHoliday = this.holidayDates.includes(current.getTime());
            if (day !== 0 && day !== 6 && !isHoliday) {
              if (current.getTime() === startDate.getTime()) {
                const dayEnd = new Date(current);
                dayEnd.setHours(we, 0, 0, 0);
                totalHours += this.calculateWorkHours(start, dayEnd);
              } else if (current.getTime() === endDate.getTime()) {
                const dayStart = new Date(current);
                dayStart.setHours(ws, 0, 0, 0);
                totalHours += this.calculateWorkHours(dayStart, end);
              } else {
                totalHours += hoursPerDay;
              }
            }
            current.setDate(current.getDate() + 1);
          }
        }

        // ปัดเป็น 0.5 step (ครึ่งวัน/เต็มวัน)
        const rawDays = totalHours / hoursPerDay;
        const days = rawDays;
        const hoursDisplay = totalHours.toFixed(2);
        const daysDisplay = days.toFixed(2);

        // ถ้าเป็น 0 วัน แสดงว่าเลือกวันหยุด
        if (days === 0 && startDate.getTime() === endDate.getTime()) {
          const day = startDate.getDay();
          if (day === 0 || day === 6) {
            return '0 วัน (วันหยุดสุดสัปดาห์)';
          } else if (this.holidayDates.includes(startDate.getTime())) {
            return '0 วัน (วันหยุดนักขัตฤกษ์)';
          }
        }
        return `${daysDisplay} วัน (${hoursDisplay} ชม.)`;
      }
      return '0 วัน (0 ชม.)';
    },
    leaveTypesWithQuota() {
      return this.leaveTypes.map(type => {
        const quota = this.quotaData[type.value];
        const disabled = quota && quota.remainingDays <= 0;
        return {
          ...type,
          disabled: disabled
        };
      });
    }
  },
  methods: {
    // Add N working days (Mon-Fri, non-holiday) to a date, counting fromDate itself
    addWorkingDays(fromDate, days) {
      const result = new Date(fromDate);
      let count = 0;
      // Count fromDate if it's a working day
      const d0 = result.getDay();
      if (d0 !== 0 && d0 !== 6 && !this.holidayDates.includes(result.getTime())) {
        count++;
      }
      while (count < days) {
        result.setDate(result.getDate() + 1);
        const day = result.getDay();
        const isHoliday = this.holidayDates.includes(result.getTime());
        if (day !== 0 && day !== 6 && !isHoliday) {
          count++;
        }
      }
      // move one more day so that 'days' working days have fully passed
      result.setDate(result.getDate() + 1);
      return result;
    },
    // Check if date is in advance days period (working days)
    isAdvanceDay(dateObj) {
      if (!this.selectedLeaveTypeAdvanceDays || this.isLevel2Approver || this.formData.leaveType === 'sick' || this.formData.leaveType === 'ลาป่วย') return false;
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const checkDate = new Date(dateObj.year, dateObj.month, dateObj.day);
      checkDate.setHours(0, 0, 0, 0);
      if (checkDate <= today) return false;
      // Count working days from today (inclusive) up to checkDate (exclusive)
      let workingDays = 0;
      const cur = new Date(today);
      while (cur < checkDate) {
        const d = cur.getDay();
        if (d !== 0 && d !== 6 && !this.holidayDates.includes(cur.getTime())) {
          workingDays++;
        }
        cur.setDate(cur.getDate() + 1);
      }
      return workingDays < this.selectedLeaveTypeAdvanceDays;
    },
    getDateClass(dateObj) {
      const checkDate = new Date(dateObj.year, dateObj.month, dateObj.day);
      checkDate.setHours(0, 0, 0, 0);
      const dayOfWeek = checkDate.getDay();
      // Weekends and holidays always show red
      if (dayOfWeek === 0 || dayOfWeek === 6 || this.holidayDates.includes(checkDate.getTime())) {
        return 'holiday-date';
      }
      if (this.isAdvanceDay(dateObj)) {
        return 'advance-day-blocked';
      }
      return '';
    },
    // รวม date + time เป็น DateTime
    updateStartDateTime() {
      if (this.formData.startDate) {
        // ถ้ายังไม่ได้เลือกเวลา ใช้เวลาเริ่มงาน
        if (!this.formData.startTime) {
          this.formData.startTime = this.workHours.start_time;
        }
        const [hours, minutes] = this.formData.startTime.split(':').map(Number);
        const date = new Date(this.formData.startDate);
        date.setHours(hours, minutes, 0, 0);
        this.formData.startDateTime = date;
      }
    },
    updateEndDateTime() {
      if (this.formData.endDate) {
        // ถ้ายังไม่ได้เลือกเวลา ใช้เวลาเลิกงาน
        if (!this.formData.endTime) {
          this.formData.endTime = this.workHours.end_time;
        }
        const [hours, minutes] = this.formData.endTime.split(':').map(Number);
        const date = new Date(this.formData.endDate);
        date.setHours(hours, minutes, 0, 0);
        this.formData.endDateTime = date;
      }
    },
    // คำนวณชั่วโมงทำงานระหว่างสองเวลา (ใช้ workHours ของ role)
    calculateWorkHours(start, end) {
      // คำนวณเป็นนาทีเพื่อหลีกเลี่ยง floating point error
      const startMinutes = start.getHours() * 60 + start.getMinutes();
      const endMinutes = end.getHours() * 60 + end.getMinutes();
      const [ws, wsm = 0] = this.workHours.start_time.split(':').map(Number);
      const [we, wem = 0] = this.workHours.end_time.split(':').map(Number);
      const [ls, lsm = 0] = this.workHours.lunch_start.split(':').map(Number);
      const [le, lem = 0] = this.workHours.lunch_end.split(':').map(Number);
      const wsMin = ws * 60 + wsm,
        weMin = we * 60 + wem,
        lsMin = ls * 60 + lsm,
        leMin = le * 60 + lem;
      let minutes = 0;
      // ช่วงเช้า
      const morningStart = Math.max(startMinutes, wsMin);
      const morningEnd = Math.min(endMinutes, lsMin);
      if (morningEnd > morningStart) {
        minutes += morningEnd - morningStart;
      }
      // ช่วงบ่าย
      const afternoonStart = Math.max(startMinutes, leMin);
      const afternoonEnd = Math.min(endMinutes, weMin);
      if (afternoonEnd > afternoonStart) {
        minutes += afternoonEnd - afternoonStart;
      }
      return Math.max(0, minutes / 60);
    },
    async loadLeaveTypes() {
      try {
        const response = await axios.get('/api/leave/leave-types');
        this.leaveTypes = response.data;
      } catch (error) {
        // Fallback to default types if API fails
        this.leaveTypes = [{
          label: 'ลาป่วย',
          value: 'sick'
        }, {
          label: 'ลากิจ',
          value: 'personal'
        }, {
          label: 'ลาพักร้อน',
          value: 'vacation'
        }];
      }
    },
    optionDisabled(option) {
      return option.disabled;
    },
    async loadQuotaData() {
      try {
        const userId = localStorage.getItem('soc_user_id');
        const response = await axios.get(`/api/leave/quota/${userId}`);
        this.quotaData = response.data;

        // Update selected quota if leave type is already selected
        if (this.formData.leaveType) {
          this.selectedQuota = this.quotaData[this.formData.leaveType];
        }
      } catch (error) {
        this.$toast.add({
          severity: 'error',
          summary: 'โหลดโควต้าไม่สำเร็จ',
          detail: 'กรุณารีเฟรชหน้าเว็บ',
          life: 4000
        });
      }
    },
    async loadHolidays() {
      try {
        const response = await axios.get('/api/leave/holidays');
        this.holidays = response.data;
      } catch {/* ignore */}
    },
    async checkLevel2Approver() {
      try {
        const userId = localStorage.getItem('soc_user_id');
        if (!userId) return;
        const response = await axios.get(`/api/leave/is-level2-approver/${userId}`);
        this.isLevel2Approver = response.data.isLevel2Approver || false;
        if (this.isLevel2Approver) {
          this.allUsersForLeave = this.users.map(u => ({
            ...u,
            displayName: `${u.firstname} ${u.lastname}`.trim()
          }));
          // เพิ่มตัวเองด้วย
          const currentUserRole = localStorage.getItem('soc_role') || 'user';
          const currentUser = {
            id: parseInt(userId),
            displayName: this.currentUserName,
            position: this.currentUserPosition,
            role: currentUserRole
          };
          this.allUsersForLeave.unshift(currentUser);
        }
      } catch {/* ignore */}
    },
    async loadWorkHours() {
      try {
        const role = localStorage.getItem('soc_role') || 'user';
        const userId = localStorage.getItem('soc_user_id');
        this.workHours = await this.fetchWorkHours(userId, role);
        this.generateAllowedTimes();
      } catch {
        this.workHours = {
          start_time: '09:00',
          end_time: '18:00',
          lunch_start: '12:00',
          lunch_end: '13:00'
        };
        this.generateAllowedTimes();
      }
    },
    async fetchWorkHours(userId, role) {
      const fmt = t => t?.substring(0, 5);
      const defaults = {
        start_time: '09:00',
        end_time: '18:00',
        lunch_start: '12:00',
        lunch_end: '13:00'
      };
      // เช็ค user-level ก่อน
      if (userId) {
        try {
          const res = await axios.get(`/api/settings/user-work-hours`);
          const found = res.data.find(u => u.user_id === parseInt(userId));
          if (found) return {
            start_time: fmt(found.start_time),
            end_time: fmt(found.end_time),
            lunch_start: fmt(found.lunch_start),
            lunch_end: fmt(found.lunch_end)
          };
        } catch {/* fallthrough */}
      }
      // fallback role
      try {
        const res = await axios.get(`/api/settings/role-work-hours/${role}`);
        return {
          start_time: fmt(res.data.start_time) || defaults.start_time,
          end_time: fmt(res.data.end_time) || defaults.end_time,
          lunch_start: fmt(res.data.lunch_start) || defaults.lunch_start,
          lunch_end: fmt(res.data.lunch_end) || defaults.lunch_end
        };
      } catch {
        return defaults;
      }
    },
    generateAllowedTimes() {
      const times = [];
      const [startH, startM] = this.workHours.start_time.split(':').map(Number);
      const [endH, endM] = this.workHours.end_time.split(':').map(Number);
      const [lunchStartH] = this.workHours.lunch_start.split(':').map(Number);
      const [lunchEndH] = this.workHours.lunch_end.split(':').map(Number);
      let h = startH,
        m = startM;
      while (h < endH || h === endH && m <= endM) {
        // ข้ามช่วงพักเที่ยง (ยกเว้นเวลาเริ่มและสิ้นสุดพัก)
        if (h >= lunchStartH && h < lunchEndH && !(h === lunchStartH && m === 0)) {
          h = lunchEndH;
          m = 0;
          continue;
        }
        const timeStr = `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
        times.push({
          label: timeStr,
          value: timeStr
        });
        m += 30;
        if (m >= 60) {
          m = 0;
          h++;
        }
      }
      this.allowedTimes = times;
    },
    onLeaveTypeChange() {
      if (this.formData.leaveType && this.quotaData[this.formData.leaveType]) {
        this.selectedQuota = this.quotaData[this.formData.leaveType];
      } else {
        this.selectedQuota = null;
      }

      // Clear dates if they're before the new minStartDate
      const minDate = this.minStartDate;
      this.calendarViewDate = new Date(minDate);
      if (this.formData.startDate && new Date(this.formData.startDate) < minDate) {
        this.formData.startDate = null;
        this.formData.startTime = null;
        this.formData.startDateTime = null;
      }
      if (this.formData.endDate && new Date(this.formData.endDate) < minDate) {
        this.formData.endDate = null;
        this.formData.endTime = null;
        this.formData.endDateTime = null;
      }
    },
    async onLeaveUserChange() {
      if (!this.selectedLeaveUser) {
        this.quotaData = {};
        this.selectedQuota = null;
        return;
      }
      try {
        // โหลด work hours ของ user ที่เลือก
        const userRole = this.selectedLeaveUser.role || 'user';
        const userId = this.selectedLeaveUser.id;
        this.workHours = await this.fetchWorkHours(userId, userRole);
        this.generateAllowedTimes();

        // โหลด quota
        const response = await axios.get(`/api/leave/quota/${this.selectedLeaveUser.id}`);
        this.quotaData = response.data;
        if (this.formData.leaveType) {
          this.selectedQuota = this.quotaData[this.formData.leaveType] || null;
        }
      } catch {
        this.quotaData = {};
        this.selectedQuota = null;
      }
    },
    getQuotaClass(remainingDays) {
      if (remainingDays <= 0) return 'quota-zero';
      if (remainingDays <= 2) return 'quota-low';
      return 'quota-normal';
    },
    async submitForm() {
      // Validate user selection for level 2 approver
      if (this.isLevel2Approver && !this.selectedLeaveUser) {
        this.$toast.add({
          severity: 'error',
          summary: 'กรุณาเลือกพนักงาน',
          detail: 'กรุณาเลือกพนักงานที่ต้องการลาย้อนหลัง',
          life: 4000
        });
        return;
      }
      if (!this.formData.leaveType) {
        this.$toast.add({
          severity: 'error',
          summary: 'กรุณากรอกข้อมูล',
          detail: 'เลือกประเภทการลาก่อนส่งคำขอ',
          life: 4000
        });
        return;
      }

      // Check quota before submitting
      if (this.selectedQuota && this.selectedQuota.remainingDays <= 0) {
        this.$toast.add({
          severity: 'error',
          summary: 'โควต้าหมด',
          detail: 'โควต้าการลาประเภทนี้ใช้หมดแล้ว กรุณาเลือกประเภทอื่น',
          life: 4000
        });
        return;
      }

      // Check if requested days exceed remaining quota
      const requestedDays = this.calculateTotalDays();
      if (this.selectedQuota && requestedDays > this.selectedQuota.remainingDays) {
        this.$toast.add({
          severity: 'error',
          summary: 'เกินโควต้า',
          detail: `ขอลา ${requestedDays} วัน แต่เหลือโควต้า ${this.selectedQuota.remainingDays} วัน`,
          life: 4000
        });
        return;
      }

      // Check advance days requirement (skip for level 2 approver - can submit retroactive leave)
      if (!this.isLevel2Approver && this.formData.leaveType !== 'sick' && this.formData.leaveType !== 'ลาป่วย') {
        const selectedLeaveType = this.leaveTypes.find(t => t.value === this.formData.leaveType);
        if (selectedLeaveType && selectedLeaveType.advance_days > 0 && this.formData.startDateTime) {
          const today = new Date();
          today.setHours(0, 0, 0, 0);
          const startDate = new Date(this.formData.startDateTime);
          startDate.setHours(0, 0, 0, 0);
          let workingDays = 0;
          const cur = new Date(today);
          while (cur < startDate) {
            const d = cur.getDay();
            if (d !== 0 && d !== 6 && !this.holidayDates.includes(cur.getTime())) {
              workingDays++;
            }
            cur.setDate(cur.getDate() + 1);
          }
          if (workingDays < selectedLeaveType.advance_days) {
            this.$toast.add({
              severity: 'error',
              summary: 'ลาล่วงหน้าไม่เพียงพอ',
              detail: `${selectedLeaveType.label} ต้องลาล่วงหน้าอย่างน้อย ${selectedLeaveType.advance_days} วันทำการ (คุณลาล่วงหน้า ${workingDays} วันทำการ)`,
              life: 5000
            });
            return;
          }
        }
      }
      if (this.formData.startDateTime && this.formData.endDateTime) {
        if (new Date(this.formData.endDateTime) < new Date(this.formData.startDateTime)) {
          this.$toast.add({
            severity: 'error',
            summary: 'วันที่ไม่ถูกต้อง',
            detail: 'วันสิ้นสุดต้องไม่ก่อนวันเริ่มลา',
            life: 4000
          });
          return;
        }
      }
      try {
        // Upload files first if any
        let uploadedFiles = [];
        if (this.formData.attachments && this.formData.attachments.length > 0) {
          const formData = new FormData();
          this.formData.attachments.forEach(file => {
            formData.append('files', file);
          });
          const uploadResponse = await axios.post('/api/files/upload?type=leave', formData, {
            headers: {
              'Content-Type': 'multipart/form-data'
            }
          });
          uploadedFiles = uploadResponse.data.files;
        }

        // Calculate total days
        const totalDays = this.calculateTotalDays();

        // Determine user_id - use selected user if level 2 approver, otherwise current user
        const targetUserId = this.isLevel2Approver && this.selectedLeaveUser ? this.selectedLeaveUser.id : localStorage.getItem('soc_user_id');

        // Prepare data for API
        const leaveData = {
          user_id: targetUserId,
          leave_type: this.formData.leaveType,
          start_datetime: this.formatDateTime(this.formData.startDateTime),
          end_datetime: this.formatDateTime(this.formData.endDateTime),
          total_days: totalDays,
          reason: this.formData.reason || 'ไม่ระบุ',
          has_delegation: this.formData.delegationOption === 'yes',
          delegate_name: this.formData.delegateName || null,
          delegate_position: this.formData.delegatePosition || null,
          delegate_department: this.formData.delegateDepartment || null,
          delegate_contact: this.formData.delegateContact || null,
          work_details: this.formData.workDetails || null,
          attachments: uploadedFiles
        };

        // Send to backend
        const response = await axios.post('/api/leave', leaveData, {
          headers: {}
        });
        this.$toast.add({
          severity: 'success',
          summary: 'สำเร็จ',
          detail: 'บันทึกคำขอลางานเรียบร้อยแล้ว',
          life: 3000
        });
        this.$emit('submit-leave', response.data);
        this.resetForm();
      } catch (error) {
        let errorMessage = 'กรุณาลองใหม่อีกครั้ง หรือติดต่อผู้ดูแลระบบ';
        if (error.response?.data?.error) {
          errorMessage = error.response.data.error;
        }
        this.$toast.add({
          severity: 'error',
          summary: 'บันทึกไม่สำเร็จ',
          detail: errorMessage,
          life: 5000
        });
      }
    },
    calculateTotalDays() {
      if (this.formData.startDateTime && this.formData.endDateTime) {
        const start = new Date(this.formData.startDateTime);
        const end = new Date(this.formData.endDateTime);
        const [ws, wsm = 0] = this.workHours.start_time.split(':').map(Number);
        const [we, wem = 0] = this.workHours.end_time.split(':').map(Number);
        const [ls, lsm = 0] = this.workHours.lunch_start.split(':').map(Number);
        const [le, lem = 0] = this.workHours.lunch_end.split(':').map(Number);
        const hoursPerDay = (ls * 60 + lsm - (ws * 60 + wsm) + (we * 60 + wem) - (le * 60 + lem)) / 60;
        let totalHours = 0;
        const startDate = new Date(start);
        startDate.setHours(0, 0, 0, 0);
        const endDate = new Date(end);
        endDate.setHours(0, 0, 0, 0);
        if (startDate.getTime() === endDate.getTime()) {
          const day = startDate.getDay();
          if (day !== 0 && day !== 6 && !this.holidayDates.includes(startDate.getTime())) {
            totalHours = this.calculateWorkHours(start, end);
          }
        } else {
          const current = new Date(startDate);
          while (current <= endDate) {
            const day = current.getDay();
            const isHoliday = this.holidayDates.includes(current.getTime());
            if (day !== 0 && day !== 6 && !isHoliday) {
              if (current.getTime() === startDate.getTime()) {
                const dayEnd = new Date(current);
                dayEnd.setHours(we, 0, 0, 0);
                totalHours += this.calculateWorkHours(start, dayEnd);
              } else if (current.getTime() === endDate.getTime()) {
                const dayStart = new Date(current);
                dayStart.setHours(ws, 0, 0, 0);
                totalHours += this.calculateWorkHours(dayStart, end);
              } else {
                totalHours += hoursPerDay;
              }
            }
            current.setDate(current.getDate() + 1);
          }
        }

        // ปัดเป็น 0.5 step (ครึ่งวัน/เต็มวัน)
        const rawDays = totalHours / hoursPerDay;
        return Math.round(rawDays * 10000) / 10000;
      }
      return 0;
    },
    formatDateTime(date) {
      if (!date) return null;
      const d = new Date(date);
      const offset = d.getTimezoneOffset() * 60000;
      return new Date(d.getTime() - offset).toISOString().slice(0, 19);
    },
    resetForm() {
      this.formData = {
        leaveType: '',
        startDate: null,
        startTime: null,
        endDate: null,
        endTime: null,
        startDateTime: null,
        endDateTime: null,
        reason: '',
        delegationOption: 'no',
        delegateName: '',
        delegatePosition: '',
        delegateDepartment: '',
        delegateContact: '',
        workDetails: '',
        attachments: [],
        quickLeave: null
      };
      this.selectedDelegate = null;
      this.selectedLeaveUser = null;
      this.selectedQuota = null;
      // Reload quota for current user if level 2 approver
      if (this.isLevel2Approver) {
        this.quotaData = {};
      } else {
        this.loadQuotaData();
      }
    },
    handleFileUpload(event) {
      const files = Array.from(event.target.files);
      this.formData.attachments = [...this.formData.attachments, ...files];
    },
    removeFile(index) {
      this.formData.attachments.splice(index, 1);
    },
    async loadUsers() {
      try {
        const response = await axios.get('/api/users');
        if (response.data && Array.isArray(response.data)) {
          // กรองผู้ใช้ปัจจุบันออก
          const currentUserName = this.currentUserName;
          this.users = response.data.filter(user => {
            const userName = `${user.firstname} ${user.lastname}`.trim();
            return userName !== currentUserName;
          }).map(user => ({
            ...user,
            displayName: `${user.firstname} ${user.lastname}${user.nickname ? ` (${user.nickname})` : ''}`.trim()
          }));
          this.filteredUsers = this.users.slice(0, this.maxDisplayUsers);
        } else {
          this.setFallbackUsers();
        }
      } catch (error) {
        this.setFallbackUsers();
      }
    },
    setFallbackUsers() {
      this.users = [{
        id: 1,
        username: 'admin',
        firstname: 'Admin',
        lastname: 'User',
        role: 'admin',
        displayName: 'Admin User'
      }, {
        id: 2,
        username: 'hr',
        firstname: 'HR',
        lastname: 'Manager',
        role: 'hr',
        displayName: 'HR Manager'
      }, {
        id: 3,
        username: 'john',
        firstname: 'John',
        lastname: 'Doe',
        role: 'user',
        displayName: 'John Doe'
      }];
      this.filteredUsers = this.users;
    },
    searchUsers(event) {
      const query = event.query.toLowerCase().trim();
      if (query === '') {
        // แสดงแค่ 50 คนแรกเมื่อไม่มีการค้นหา
        this.filteredUsers = this.users.slice(0, this.maxDisplayUsers);
      } else {
        // ค้นหาและจำกัดผลลัพธ์
        const filtered = this.users.filter(user => user.displayName.toLowerCase().includes(query) || user.username.toLowerCase().includes(query) || user.position && user.position.toLowerCase().includes(query) || user.department && user.department.toLowerCase().includes(query));
        this.filteredUsers = filtered.slice(0, this.maxDisplayUsers);
      }
    },
    showAllUsers() {
      // แสดงแค่ 50 คนแรกเมื่อคลิก dropdown
      this.filteredUsers = this.users.slice(0, this.maxDisplayUsers);
    },
    onDelegateSelect(event) {
      const user = event.value;
      if (user) {
        this.formData.delegateName = user.displayName;
        this.formData.delegatePosition = user.position || '';
        this.formData.delegateDepartment = user.department || '';
      }
    },
    setQuickLeave(type) {
      this.formData.quickLeave = type;

      // ถ้ายังไม่เลือกวันเริ่ม ให้ใช้วันนี้หรือ minStartDate
      if (!this.formData.startDate) {
        this.formData.startDate = new Date(this.minStartDate);
      }

      // ตั้งค่าวันสิ้นสุดเป็นวันเดียวกับวันเริ่ม
      this.formData.endDate = new Date(this.formData.startDate);
      const startTime = this.workHours.start_time;
      const endTime = this.workHours.end_time;
      const lunchStart = this.workHours.lunch_start;
      const lunchEnd = this.workHours.lunch_end;
      if (type === 'half_morning') {
        this.formData.startTime = startTime;
        this.formData.endTime = lunchStart;
      } else if (type === 'half_afternoon') {
        this.formData.startTime = lunchEnd;
        this.formData.endTime = endTime;
      } else if (type === 'full') {
        this.formData.startTime = startTime;
        this.formData.endTime = endTime;
      }
      this.updateStartDateTime();
      this.updateEndDateTime();
    }
  }
};
